// ---------------------------------------------------------------------------
// Ficha · Comprobar el número de oportunidad que llega en el enlace.
// Entrada ($json): lo que recibe el Webhook. La dirección es
//   .../webhook/ficha?oportunidad_id=248
// y n8n guarda lo que va detrás del "?" en $json.query.
// Salida: { valido, oportunidad_id }.
// Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// El valor tal como vino en la dirección. "?." evita un error si no hay
// "query"; "?? ''" lo convierte en texto vacío si no hay número.
const crudo = $json.query?.oportunidad_id ?? '';

// Siempre como texto y sin espacios al principio y al final.
const texto = String(crudo).trim();

// Regla: solo cifras, sin un 0 delante y como mucho 10 cifras.
//   ^ y $         -> el texto ENTERO tiene que cumplir la regla
//   [1-9]         -> la primera cifra no puede ser 0 (así no pasa "0" ni "007")
//   [0-9]{0,9}    -> después, de 0 a 9 cifras más (10 en total como máximo)
// Un número de más de 10 cifras no cabe en la columna de la base de datos;
// uno de 10 que no cabe lo rechaza el backend con un 404 (comprobado en sus pruebas).
const valido = /^[1-9][0-9]{0,9}$/.test(texto);

// Si es válido, se pasa como número; si no, null (no se usa para nada).
return { json: { valido, oportunidad_id: valido ? Number(texto) : null } };

// ---------------------------------------------------------------------------
// Ficha · Construir la página HTML de la ficha completa (o su página de error).
// Entrada ($json): la respuesta COMPLETA de GET /oportunidades/{id}/ficha,
//   { statusCode, headers, body }, o, si no hubo conexión, un dato con "error"
//   y SIN statusCode (llega por la salida de error de leer_ficha).
// Salida: { html, codigo, aviso_tecnico, mensaje_tecnico }
//   html            -> la página que verá administración
//   codigo          -> el código HTTP con el que se responde al navegador
//   aviso_tecnico   -> true si el fallo es técnico (se avisará a WF4)
//   mensaje_tecnico -> texto para el aviso técnico (sin datos del cliente)
// Determinista: ningún LLM interviene. Todo dato variable pasa por esc().
// CAMBIO (2026-10-10, noche): en las páginas de error la cabecera dice
// "Aviso"; el título concreto sale una sola vez, en el cuerpo.
// ---------------------------------------------------------------------------

// ---- 1. Datos de partida ----------------------------------------------------
// Código HTTP (undefined si no hubo conexión) y cuerpo ("?? {}": objeto vacío).
const estado = $json.statusCode;
const f = $json.body ?? {};
// Número de oportunidad: el que ya validó validar_enlace (nunca el de la URL en bruto).
const op = $('validar_enlace').item.json.oportunidad_id;
// Dirección pública de esta misma página, para los enlaces a OTRAS fichas.
// Absoluta: dentro del marco aislado de n8n las direcciones relativas no funcionan.
const FICHA_BASE = 'https://TU-DOMINIO.ngrok-free.dev/webhook/ficha';

// ---- 2. Colores de la empresa (los mismos que el email de WF2) -------------
const AZUL = '#0B3C5D';            // cabecera y títulos
const TURQUESA = '#1F8A8A';        // acentos y franjas
const TURQUESA_CLARO = '#E3F2F1';  // fondo de la caja de importes
const TEXTO = '#1F2933';           // texto principal
const SUAVE = '#5B6B79';           // etiquetas y texto secundario

// ---- 3. Escapar texto antes de meterlo en HTML -------------------------------
// Nombres, informes y textos de visitas los escribieron personas: esc() cambia
// los caracteres especiales de HTML por su forma inofensiva.
function esc(valor) {
  return String(valor)
    .replace(/&/g, '&amp;')    // el & primero, para no estropear los siguientes
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// ---- 4. Formatos españoles (solo para MOSTRAR) ------------------------------
const eur = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' });
const num = new Intl.NumberFormat('es-ES', { maximumFractionDigits: 2 });
// Importe en texto exacto ("87120.00") -> "87.120,00 €"; si falta, un guion.
function dinero(t) { return (t === null || t === undefined) ? '—' : eur.format(Number(t)); }
// Número en texto ("90.0") -> "90"; si falta, un guion.
function numero(t) { return (t === null || t === undefined) ? '—' : num.format(Number(t)); }
// Fecha con desfase -> "03/10/2026, 12:15" en hora de Madrid; si falta, un guion.
function fecha(t) {
  if (!t) return '—';
  return new Date(t).toLocaleString('es-ES', {
    timeZone: 'Europe/Madrid', day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit',
  });
}
// true -> "Sí", false -> "No", otra cosa -> guion.
function siNo(v) { return v === true ? 'Sí' : v === false ? 'No' : '—'; }

// ---- 5. Diccionarios: códigos del backend -> texto legible ------------------
const TIPOS = { bano: 'Baño', cocina: 'Cocina', integral_vivienda: 'Reforma integral de vivienda',
  parcial_acabados: 'Acabados parciales' };
const ACABADOS = { basico: 'Básico', medio: 'Medio', alto: 'Alto' };
const MOTIVOS_GATE = { cambios_estructurales: 'Cambios estructurales',
  importe_superior_umbral: 'Importe superior al umbral', ambos: 'Cambios estructurales e importe superior al umbral' };
const ESTADOS = { nueva: 'Nueva', cualificada: 'Cualificada', pendiente_aprobacion: 'Pendiente de llamada (Gate)',
  visita_agendada: 'Visita agendada', presupuesto_enviado: 'Presupuesto enviado',
  seguimiento_pendiente: 'Seguimiento pendiente', ganada: 'Ganada', perdida: 'Perdida' };
const ESTADOS_VISITA = { solicitada: 'Pedida por el cliente (sin confirmar)', confirmada: 'Confirmada',
  completada: 'Realizada', cancelada: 'Cancelada' };
const RESULTADOS = { visita_acordada: 'Visita acordada', descartar: 'Descartado' };
const MOTIVOS_DESCARTE = { precio: 'Precio', plazo: 'Plazo', no_contesta: 'No contesta',
  proyecto_no_viable: 'Proyecto no viable', otro: 'Otro' };
const EVENTOS = { alta: 'Solicitud recibida', presupuesto_calculado: 'Presupuesto calculado',
  visita_solicitada: 'Visita pedida', gate_decision_registrada: 'Resultado de la llamada registrado',
  seguimiento_abierto: 'Seguimiento abierto' };
// Traduce con un diccionario; si el código no está, lo enseña tal cual; si no hay, guion.
function txt(dic, codigo) { return dic[codigo] ?? codigo ?? '—'; }

// ---- 6. Piezas de HTML reutilizables ----------------------------------------
// Una fila "etiqueta | valor". El VALOR siempre pasa por esc().
function fila(etiqueta, valor) {
  return `<tr><td style="padding:5px 12px 5px 0;width:40%;color:${SUAVE};font-size:13px;vertical-align:top;">${etiqueta}</td>` +
         `<td style="padding:5px 0;color:${TEXTO};font-size:14px;font-weight:bold;">${esc(valor)}</td></tr>`;
}
// Una sección: título turquesa y su contenido (ya construido).
function seccion(titulo, contenido) {
  return `<div style="padding:16px 24px 4px;"><div style="font-size:12px;letter-spacing:1px;text-transform:uppercase;` +
         `color:${TURQUESA};font-weight:bold;border-bottom:2px solid ${TURQUESA_CLARO};padding-bottom:6px;margin-bottom:6px;">` +
         `${titulo}</div>${contenido}</div>`;
}
// Una tabla con filas.
function tabla(filas) { return `<table style="width:100%;border-collapse:collapse;">${filas}</table>`; }
// Un texto en gris cuando una lista está vacía.
function vacio(texto) { return `<p style="color:${SUAVE};font-size:14px;margin:4px 0;">${texto}</p>`; }
// La página completa: tarjeta blanca con cabecera azul. "subtitulo" es la
// línea pequeña bajo el nombre de la empresa.
function pagina(subtitulo, cuerpo) {
  return `<div style="font-family:Arial,Helvetica,sans-serif;max-width:680px;margin:24px auto;color:${TEXTO};` +
         `border:1px solid #E5E9ED;border-radius:8px;">` +
         `<div style="background:${AZUL};color:#FFFFFF;padding:16px 24px;border-radius:8px 8px 0 0;">` +
         `<div style="font-size:18px;font-weight:bold;">Reformas Integrales Amedida · Ficha del cliente</div>` +
         `<div style="font-size:13px;color:#A7D8D6;margin-top:4px;">${subtitulo}</div></div>` +
         `<div style="height:4px;background:${TURQUESA};"></div>` + cuerpo +
         `<div style="padding:16px 24px;font-size:12px;color:${SUAVE};border-top:1px solid #E5E9ED;margin-top:12px;">` +
         `Uso interno de administración: contiene datos personales. No reenviar.</div></div>`;
}
// Atajo para las páginas de error. CAMBIO: la cabecera dice siempre "Aviso";
// el título concreto va solo en el cuerpo, una vez.
function error(titulo, mensaje, codigo, tecnico, mensajeTecnico) {
  const cuerpo = `<div style="padding:20px 24px;"><p style="font-size:18px;font-weight:bold;color:#8A4B00;margin:0 0 8px;">` +
                 `${esc(titulo)}</p><p style="margin:0;">${esc(mensaje)}</p></div>`;
  return { json: { html: pagina('Aviso', cuerpo), codigo, aviso_tecnico: tecnico, mensaje_tecnico: mensajeTecnico } };
}

// ---- 7. Respuestas que NO son 200 -------------------------------------------
// Sin código: no hubo conexión con el backend (uvicorn apagado o caído).
if (estado === undefined) {
  return error('Sistema no disponible', 'No se ha podido conectar con el sistema. Inténtalo de nuevo en unos minutos.',
    503, true, 'Sin conexión con el backend al leer la ficha');
}
// 404: la oportunidad no existe. Es un error del enlace, no técnico.
if (estado === 404) {
  return error('Oportunidad no encontrada', `No existe ninguna oportunidad con el número ${op}.`, 404, false, '');
}
// 401: la llave de administración no vale. Técnico.
if (estado === 401) {
  return error('Error de configuración', 'La página no tiene una llave válida. Se ha avisado al responsable técnico.',
    500, true, 'GET /ficha respondió 401 (llave X-Gate-Secret)');
}
// Cualquier otro código distinto de 200: técnico.
if (estado !== 200) {
  return error('Error inesperado', `El sistema respondió con el código ${estado}. Se ha avisado al responsable técnico.`,
    500, true, `GET /ficha respondió ${estado}`);
}

// ---- 8. Respuesta 200: las secciones de la ficha ----------------------------
const c = f.contacto;   // nombre, email, telefono, origen
const r = f.reforma;    // tipo, m2, acabados, cambios estructurales
const p = f.presupuesto; // null si no hay presupuesto

// Contacto: el de ESTA solicitud, o un aviso si es un lead antiguo.
const htmlContacto = c.origen === 'solicitud'
  ? tabla(fila('Nombre', c.nombre ?? '—') + fila('Teléfono', c.telefono ?? '—') + fila('Email', c.email ?? '—'))
  : vacio('Contacto no disponible en esta solicitud (lead anterior al 25/09/2026).');

// Solicitud: qué pidió el cliente y cuándo.
const htmlSolicitud = tabla(
  fila('Estado actual', txt(ESTADOS, f.estado_oportunidad)) +
  fila('Recibida', fecha(f.fecha_solicitud)) +
  fila('Tipo de reforma', txt(TIPOS, r.tipo_reforma)) +
  fila('Superficie', `${numero(r.m2)} m²`) +
  fila('Acabados', txt(ACABADOS, r.nivel_acabados)) +
  fila('Cambios estructurales', siNo(r.incluye_cambios_estructurales)));

// Fotos: una fila por ruta, o "Sin fotos".
const htmlFotos = (f.fotos && f.fotos.length)
  ? tabla(f.fotos.map((ruta, i) => fila(`Foto ${i + 1}`, ruta)).join(''))
  : vacio('Sin fotos.');

// Presupuesto: caja destacada con IVA y detalle; o un aviso si no hay.
const htmlPresupuesto = p === null || p === undefined
  ? vacio('Todavía no hay presupuesto calculado.')
  : `<div style="background:${TURQUESA_CLARO};border-left:4px solid ${TURQUESA};border-radius:6px;padding:12px 16px;margin:6px 0;">` +
    `<div style="font-size:12px;color:${SUAVE};">Horquilla (IVA ${esc(numero(p.iva_pct_aplicado))} % incluido)</div>` +
    `<div style="font-size:20px;font-weight:bold;color:${AZUL};margin-top:4px;">` +
    `${esc(dinero(p.importe_min_con_iva))} – ${esc(dinero(p.importe_max_con_iva))}</div></div>` +
    tabla(
      fila('Fecha del presupuesto', fecha(p.fecha_presupuesto)) +
      fila('Horquilla sin IVA', `${dinero(p.importe_min_sin_iva)} – ${dinero(p.importe_max_sin_iva)}`) +
      fila('¿Requirió revisión (Gate)?', siNo(p.requiere_aprobacion)) +
      fila('Motivo del Gate', p.motivo_gate ? txt(MOTIVOS_GATE, p.motivo_gate) : '—') +
      fila('Umbral vigente (sin IVA)', dinero(p.umbral_gate_vigente)));

// Visitas: todas, también canceladas, cada una con su texto.
const htmlVisitas = (f.visitas && f.visitas.length)
  ? f.visitas.map((v) => tabla(
      fila('Estado', txt(ESTADOS_VISITA, v.estado_visita)) +
      fila('Fecha de la visita', fecha(v.fecha_visita)) +
      fila('Pedida el', fecha(v.fecha_solicitud_visita)) +
      fila('Texto', v.texto_cliente ?? '—'))).join('<hr style="border:none;border-top:1px dashed #E5E9ED;">')
  : vacio('Sin visitas.');

// Llamadas registradas: con su informe (los saltos de línea se conservan).
const htmlLlamadas = (f.llamadas && f.llamadas.length)
  ? f.llamadas.map((l) =>
      tabla(
        fila('Resultado', txt(RESULTADOS, l.resultado)) +
        fila('Motivo', l.motivo ? txt(MOTIVOS_DESCARTE, l.motivo) : '—') +
        fila('Registrada el', fecha(l.fecha_registro)) +
        fila('Visita', l.fecha_visita ? fecha(l.fecha_visita) : '—')) +
      `<div style="font-size:13px;color:${SUAVE};margin-top:4px;">Informe</div>` +
      `<div style="background:#F6F8FA;border-radius:4px;padding:8px 12px;font-size:14px;">` +
      `${esc(l.informe).replace(/\r?\n/g, '<br>')}</div>`).join('<hr style="border:none;border-top:1px dashed #E5E9ED;">')
  : vacio('Sin llamadas registradas.');

// Historial: los cambios de estado registrados, del más antiguo al más reciente.
const htmlHistorial = tabla((f.historial ?? []).map((e) =>
    fila(fecha(e.fecha), `${txt(EVENTOS, e.evento)} → ${txt(ESTADOS, e.estado)}`)).join('')) +
  (f.historial_cuadra
    ? ''
    : vacio('El estado actual no sale de ningún cambio registrado por el sistema (por ejemplo, se cambió a mano).'));

// Otras oportunidades del mismo email: cada una con un enlace a su propia ficha.
const htmlOtras = (f.otras_oportunidades_mismo_email && f.otras_oportunidades_mismo_email.length)
  ? tabla(f.otras_oportunidades_mismo_email.map((o) =>
      `<tr><td style="padding:5px 12px 5px 0;font-size:14px;">` +
      `<a href="${esc(FICHA_BASE + '?oportunidad_id=' + encodeURIComponent(o.oportunidad_id))}" target="_blank" ` +
      `style="color:${TURQUESA};font-weight:bold;">Oportunidad ${esc(o.oportunidad_id)}</a></td>` +
      `<td style="padding:5px 0;font-size:14px;">${esc(txt(TIPOS, o.tipo_reforma))} · ${esc(txt(ESTADOS, o.estado_oportunidad))} · ` +
      `${esc(fecha(o.fecha_solicitud))}</td></tr>`).join(''))
  : vacio('Ninguna.');

// ---- 9. La página completa -----------------------------------------------------
const cuerpo =
  seccion('Contacto', htmlContacto) +
  seccion('Solicitud', htmlSolicitud) +
  seccion('Presupuesto', htmlPresupuesto) +
  seccion('Visitas', htmlVisitas) +
  seccion('Llamadas registradas', htmlLlamadas) +
  seccion('Historial', htmlHistorial) +
  seccion('Fotos', htmlFotos) +
  seccion('Otras solicitudes con el mismo email', htmlOtras);

return { json: { html: pagina(`Oportunidad ${esc(f.oportunidad_id)}`, cuerpo), codigo: 200,
                 aviso_tecnico: false, mensaje_tecnico: '' } };
